const response = $input.first().json;
const batchSize = Math.max(1, Number($('Konfigurasi').first().json.batchSize || 1));
const products = Array.isArray(response.products) ? response.products : [];
const state = $getWorkflowStaticData('global');
state.failures = state.failures || {};
state.videoChecked = state.videoChecked || {};
const retryAfterMs = 6 * 60 * 60 * 1000;
const canRetry = (id) => {
  const checkedAt = Date.parse(state.failures[id]?.checkedAt || '');
  return !Number.isFinite(checkedAt) || Date.now() - checkedAt >= retryAfterMs;
};
const candidates = products
  .filter((product) => /^https:\/\/(?:[^/]+\.)?shopee\.co\.id\/(?:product|opaanlp)\/\d+\/\d+/.test(String(product.productUrl || '')))
  .filter((product) => canRetry(String(product.id)))
  .filter((product) => {
    const missingImage = !String(product.imageUrl || '').trim();
    const missingDescription = !String(product.description || '').trim();
    const videoNotChecked = !String(product.videoUrl || '').trim() && !state.videoChecked[String(product.id)];
    return missingImage || missingDescription || videoNotChecked;
  })
  .sort((a, b) => {
    const aIncomplete = Number(!String(a.imageUrl || '').trim() || !String(a.description || '').trim());
    const bIncomplete = Number(!String(b.imageUrl || '').trim() || !String(b.description || '').trim());
    return bIncomplete - aIncomplete;
  })
  .slice(0, batchSize);

return candidates.map((product) => ({ json: product }));

const state = $getWorkflowStaticData('global');
state.failures = state.failures || {};
state.videoPending = state.videoPending || {};
state.videoChecked = state.videoChecked || {};
state.descriptionPending = state.descriptionPending || {};

const successful = [];
for (const item of $input.all()) {
  const media = item.json;
  const productId = String(media.productId || 'unknown');
  if (!media.ok || !Array.isArray(media.images) || !media.images.length) {
    state.failures[productId] = {
      reason: media.error || 'Foto produk tidak ditemukan',
      checkedAt: new Date().toISOString(),
    };
    continue;
  }

  if (media.diagnostics?.productDataAvailable) {
    delete state.failures[productId];
    delete state.descriptionPending[productId];
    state.videoChecked[productId] = {
      checkedAt: new Date().toISOString(),
      hasVideo: Boolean(media.hasVideo),
      videoFound: Array.isArray(media.videos) && media.videos.length > 0,
    };
  } else {
    state.failures[productId] = {
      reason: media.diagnostics?.productDataError || 'Deskripsi dan video belum dapat diperiksa',
      checkedAt: new Date().toISOString(),
    };
    state.descriptionPending[productId] = {
      productUrl: media.requestedUrl,
      checkedAt: new Date().toISOString(),
    };
  }

  if (media.videoPending) {
    state.videoPending[productId] = {
      productUrl: media.requestedUrl,
      checkedAt: new Date().toISOString(),
    };
  } else {
    delete state.videoPending[productId];
  }
  successful.push({ json: media });
}

return successful;

return $input.all().map((item) => ({
  json: {
    ok: Boolean(item.json.ok),
    productId: item.json.id,
    imageUrl: item.json.imageUrl,
    galleryCount: Array.isArray(item.json.galleryUrls) ? item.json.galleryUrls.length : 0,
    videoUrl: item.json.videoUrl || '',
    descriptionSaved: Boolean(item.json.description),
    warningCount: Array.isArray(item.json.errors) ? item.json.errors.length : 0,
    completedAt: new Date().toISOString(),
  },
}));
